    },
    {
        "check_name": "t10_accessibility_scores exists",
        "passed": os.path.exists("outputs/t10_accessibility_scores.csv"),
        "message": "File exists" if os.path.exists("outputs/t10_accessibility_scores.csv") else "File does not exist"
    },
    {
        "check_name": "t10_accessibility_scores is not empty",
        "passed": os.path.getsize("outputs/t10_accessibility_scores.csv") > 0,
        "message": "File is not empty" if os.path.getsize("outputs/t10_accessibility_scores.csv") > 0 else "File is empty"
    },
    {
        "check_name": "t13_city_clusters exists",
        "passed": os.path.exists("outputs/t13_city_clusters.csv"),
        "message": "File exists" if os.path.exists("outputs/t13_city_clusters.csv") else "File does not exist"
    },
    {
        "check_name": "t13_city_clusters is not empty",
        "passed": os.path.getsize("outputs/t13_city_clusters.csv") > 0,
        "message": "File is not empty" if os.path.getsize("outputs/t13_city_clusters.csv") > 0 else "File is empty"
    }
]

# Run validation checks and write summary to JSON file
validation_summary = [
    {
        "check_name": check[
            "check_name"
        ],
        "passed": check[
            "passed"
        ],
        "message": check[
            "message"
        ]
    }
    for check in checks
    if check[
        "passed"
    ]
]

with open("outputs/t14_validation_summary.json", "w") as f:
    json.dump(
        validation_summary,
        f,
        indent=4
    )

